// blitz-recompiler: makes an executable of the original Blitz compilers run on the BlitzLLVM runtime.
//
// Only use it on programs you made or are allowed to modify and redistribute (freeware, your own programs, programs with permission).
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <iterator>
#include <map>
#include <string>
#include <vector>
#if defined(_WIN32)
#include <windows.h>
#endif
#include "commands.hpp"
#include "lift.hpp"
#include "module.hpp"

#ifndef BLITZLLVM_VERSION
#define BLITZLLVM_VERSION "0"
#endif

namespace {
	namespace fs = std::filesystem;

	void usage(char const* self)
	{
		std::cout << "blitz-recompiler V" << BLITZLLVM_VERSION << "\n"
				  << "Usage: " << self << " [options] <program.exe|module> [-- <blitzcc options>]\n"
				  << "\n"
				  << "Turns an executable made by Blitz3D, BlitzPlus or Blitz Basic into one for the BlitzLLVM runtime.\n"
				  << "Only use it on programs that you made, or that you are allowed to modify and redistribute.\n"
				  << "\n"
				  << "Options:\n"
				  << "  -o <file>        The executable to create. Defaults to the name of the input with -recompiled added.\n"
				  << "  -S, --emit-llvm  Only write the LLVM IR (.ll), don't build an executable.\n"
				  << "  --info           Describe the program (functions, globals, what it needs from the runtime) and stop.\n"
				  << "  --commands       With --info: list every command the program calls.\n"
				  << "  --blitzcc <path> The blitzcc that builds the IR. Defaults to the one next to blitz-recompiler.\n"
				  << "  --strict         Fail if any part of the program can't be translated, instead of raising a runtime error when it is used.\n"
				  << "  -v               Print every step.\n"
				  << "  -q               Print nothing except errors.\n"
				  << "  -h, --help       This text.\n"
				  << "Everything after a lone '--' is passed to blitzcc as-is (-O3, --target, ...).\n";
	}

	fs::path executable_path()
	{
#if defined(_WIN32)
		wchar_t buffer[32768];
		DWORD   n = GetModuleFileNameW(nullptr, buffer, 32768);
		return fs::path(std::wstring(buffer, n));
#else
		std::error_code ec;
		auto            p = fs::read_symlink("/proc/self/exe", ec);
		return ec ? fs::path() : p;
#endif
	}

	std::string quote(std::string const& a)
	{
#if defined(_WIN32)
		return "\"" + a + "\"";
#else
		std::string r = "'";
		for (char c : a) {
			r += (c == '\'') ? std::string("'\\''") : std::string(1, c);
		}
		return r + "'";
#endif
	}

	std::vector<uint8_t> read_file(fs::path const& p)
	{
		std::ifstream in(p, std::ios::binary);
		if (!in) {
			throw std::runtime_error("Opening '" + p.generic_string() + "' failed.");
		}
		return std::vector<uint8_t>(std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>());
	}
} // namespace

int main(int argc, char** argv)
{
	using namespace blitz::recompiler;
	fs::path                 input, output, blitzcc;
	bool                     emit_ir = false, info = false, list_commands = false, strict = false, verbose = false, quiet = false;
	std::vector<std::string> passthrough;
	try {
		for (int k = 1; k < argc; k++) {
			std::string a = argv[k];
			auto        value = [&]() -> std::string {
                if (k + 1 >= argc) {
                    throw std::runtime_error("Option " + a + " requires a value.");
                }
                return argv[++k];
			};
			if (a == "--") {
				for (k++; k < argc; k++) {
					passthrough.push_back(argv[k]);
				}
			} else if (a == "-h" || a == "--help") {
				usage(argv[0]);
				return 0;
			} else if (a == "-o") {
				output = value();
			} else if (a == "-S" || a == "--emit-llvm") {
				emit_ir = true;
			} else if (a == "--info") {
				info = true;
			} else if (a == "--commands") {
				list_commands = true;
			} else if (a == "--blitzcc") {
				blitzcc = value();
			} else if (a == "--strict") {
				strict = true;
			} else if (a == "-v") {
				verbose = true;
			} else if (a == "-q") {
				quiet = true;
			} else if (!a.empty() && a[0] == '-') {
				throw std::runtime_error("Unknown option " + a + ", see --help.");
			} else if (input.empty()) {
				input = a;
			} else {
				throw std::runtime_error("Only one input file is supported.");
			}
		}
		if (input.empty()) {
			usage(argv[0]);
			return argc > 1 ? 0 : 1;
		}

		// The module alone (the resource 1111 of an executable, without the runtime of the original) is accepted too, which is what the tests keep.
		auto bytes   = read_file(input);
		auto program = (bytes.size() >= 2 && bytes[0] == 'M' && bytes[1] == 'Z') ? load_module(bytes) : parse_module(bytes.data(), bytes.size());

		if (info) {
			std::map<symbol_kind, size_t> kinds;
			for (auto const& l : program.labels) {
				kinds[blitz_module::kind(l.name)]++;
			}
			std::cout << input.generic_string() << ": Blitz program\n"
					  << "  code and data: " << program.code.size() << " bytes (x86, 32 bit)\n"
					  << "  functions " << kinds[symbol_kind::function] << ", globals " << kinds[symbol_kind::global] << ", arrays " << kinds[symbol_kind::array]
					  << ", types " << kinds[symbol_kind::type] << ", labels " << kinds[symbol_kind::label] << "\n";
			std::map<std::string, size_t> external;
			for (auto const& r : program.relative) {
				if (!program.defined.count(r.name)) {
					external[r.name]++;
				}
			}
			size_t known = 0, total = 0;
			std::vector<std::string> support, missing;
			for (auto const& [n, count] : external) {
				if (n.compare(0, 4, "__bb") == 0) {
					support.push_back(n);
				} else if (n.compare(0, 2, "_f") == 0) {
					total++;
					if (find_command(n.substr(2))) {
						known++;
						if (list_commands) {
							std::cout << "    " << n.substr(2) << " x" << count << " -> " << find_command(n.substr(2))->symbol << "\n";
						}
					} else {
						missing.push_back(n.substr(2));
					}
				}
			}
			std::cout << "  support functions: " << support.size() << ", commands: " << total << " (" << known << " in BlitzLLVM)\n";
			for (auto const& n : missing) {
				std::cout << "    missing in BlitzLLVM: " << n << "\n";
			}
			return missing.empty() ? 0 : 1;
		}

		if (!quiet) {
			std::cout << "blitz-recompiler V" << BLITZLLVM_VERSION << "\nTranslating \"" << input.generic_string() << "\"..." << std::endl;
		}
		lift_options options;
		options.keep_going = !strict;
		options.verbose    = verbose;
		auto result        = lift(program, options);
		if (!quiet) {
			std::cout << result.functions << " functions, " << result.instructions << " instructions";
			if (result.failed_functions) {
				std::cout << ", " << result.failed_functions << " functions could not be translated";
			}
			std::cout << std::endl;
		}
		for (auto const& p : result.problems) {
			std::cerr << "warning: " << p << std::endl;
		}

		if (output.empty()) {
			output = input;
			output.replace_filename(input.stem().string() + "-recompiled");
#if defined(_WIN32)
			output.replace_extension(emit_ir ? ".ll" : ".exe");
#else
			if (emit_ir) {
				output.replace_extension(".ll");
			}
#endif
		}
		if (emit_ir) {
			std::ofstream out(output, std::ios::binary);
			out << result.ir;
			if (!out) {
				throw std::runtime_error("Writing '" + output.generic_string() + "' failed.");
			}
			return 0;
		}

		// The back-end is blitzcc, which accepts the IR.
		if (blitzcc.empty()) {
			blitzcc = executable_path().parent_path() / "blitzcc";
#if defined(_WIN32)
			blitzcc.replace_extension(".exe");
#endif
		}
		std::error_code ec;
		auto            temp = fs::temp_directory_path(ec) / ("blitz-recompiler-" + std::to_string(std::rand()));
		fs::create_directories(temp, ec);
		auto ir_file = temp / "program.ll";
		{
			std::ofstream out(ir_file, std::ios::binary);
			out << result.ir;
			if (!out) {
				throw std::runtime_error("Writing '" + ir_file.generic_string() + "' failed.");
			}
		}
		std::string command = quote(blitzcc.string()) + " -q";
		for (auto const& p : passthrough) {
			command += " " + quote(p);
		}
		command += " -o " + quote(output.string()) + " " + quote(ir_file.string());
		if (verbose) {
			std::cout << command << std::endl;
		}
		int rc = std::system(command.c_str());
		fs::remove_all(temp, ec);
		if (rc != 0) {
			std::cerr << "error: building the executable failed (blitzcc returned " << rc << ")." << std::endl;
			return 1;
		}
		if (!quiet) {
			std::cout << "Created \"" << output.generic_string() << "\"." << std::endl;
		}
		return 0;
	} catch (std::exception const& ex) {
		std::cerr << "error: " << ex.what() << std::endl;
		return 1;
	}
}
